BEGIN;
-- Target 'ฆ่า' not found for redirect 'แทง' (ID 251)
-- Redirect Fix: โทษ -> จับ
UPDATE dreams SET dream_interpretation = 'ฝันเห็นโทษ หรือจับ ฝันว่าถูกจับ หรือถูกจองจำ ทายว่า จะพ้นเคราะห์หรือจะมีโชคลาภจากการเสี่ยง (ในตำราก็ให้อธิษฐานต่างๆ ถ้าได้รับความตกใจอย่างมาก จะได้รับโชคลาภมากตามสวน)' WHERE dream_id = 255;
-- Redirect Fix: มรกต -> เพชรพลอย
UPDATE dreams SET dream_interpretation = 'ฝันเห็นมรกต หรือเพชรพลอย หญิงชายใดฝันว่า ได้เพชรพลอยใส่เก็บไว้ หรือได้เก็บแสงประกายของเพชรส่องแสงใส หมายว่า หญิงมีครรภ์จะได้บุตรเป็นผู้รักและมีวาสนาดี ชายโสดจะได้พบภรรยา คนมีเรือนจะได้บุตรหรือโชคจากทางการค้า' WHERE dream_id = 428;
-- Redirect Fix: มาลี -> มาลัย
UPDATE dreams SET dream_interpretation = 'ฝันเห็นมาลี หรือมาลัย หญิงชายใดฝันว่าได้สวมพวงมาลัย หรือพวงดอกไม้ทางที่แขนหรือที่คอ ทายว่า จะได้รับเชิญให้ร่วมงานสมรสหรืองานในโอกาสดีเป็นประมาณ' WHERE dream_id = 430;
-- Redirect Fix: มู่ลี่ -> ม่าน
UPDATE dreams SET dream_interpretation = 'หญิงชายใดฝันเห็นมู่ลี่ หรือม่านสีแดงกลางห้อง หรือม่านบังทางประตู (หน้าต่าง) ทายว่า สิ่งที่ดิ้นต่อสู้ หรือภาระเก่าตรากต่าย จะคลี่คลายอย่างรวดเร็ว มีเหตุการณ์ดีเร่งด่วนมาถึง' WHERE dream_id = 432;
-- Redirect Fix: มังดา -> ปลา
UPDATE dreams SET dream_interpretation = 'ฝันเห็นมังดา หรือปลา หญิงชายใดฝันว่าได้จับปลา ทำนายว่า จะได้ลาภ หรือได้ข่าวดี หน้าที่การงานจะดีขึ้น' WHERE dream_id = 433;
-- Redirect Fix: เพื่อน -> เพื่อน
UPDATE dreams SET dream_interpretation = 'ฝันเห็นเพื่อน หรือเพื่อน (ดูคำว่า 'เพื่อน' อีกครั้ง) เมา ฝันว่า เมาเหล้าหรือเมายา ทายว่า จะได้ความดี หากการตั้งใจไว้จะเจริญได้ตั้งขึ้นได้ดี' WHERE dream_id = 448;
-- Redirect Fix: รูปภาพ -> ภาพ
UPDATE dreams SET dream_interpretation = 'ฝันว่าเห็นตนเองเป็นเงาในกระจก หรือในน้ำ ทายว่าจะได้รับเคราะห์ หรือเจ็บป่วยเล็กๆ น้อยๆ แต่หลังพ้นเจ็บแล้วจะมีลาภ ถ้าฝันเห็นรูปภาพ หรือภาพต่างๆ ของญาติมิตร หรือภาพสิ่งต่างๆ ทายว่าจะมีการเดินทางไกล ไม่ดีและไม่ราบรื่น' WHERE dream_id = 483;
