-- Target 'ราชวงศ์' not found for redirect 'ราชินี' (ID 486)
-- Redirect Fix: ลูยโคลน -> โคลน
UPDATE dreams SET dream_interpretation = 'ฝันเห็นลูยโคลน หรือโคลน ฝันว่าได้ลุยโคลน หรือ เหยียบย่ำโคลนติดเท้าขึ้นมา ความฝันนี้จะบอกเหตุให้รู้ว่า จะเกิดทุกข์เพราะโรคภัยไข้เจ็บ หรือได้รับสิ่งอกุศลจากเหตุอื่น ๆ ควรระวังให้จงหนัก' WHERE dream_id = 515;
-- Target 'ใบเสด็ก' not found for redirect 'วัด' (ID 535)
-- Redirect Fix: สำปา -> เรือ
UPDATE dreams SET dream_interpretation = 'ฝันเห็นสำปา หรือเรือ หญิงชายได้ฝันว่า ได้นั่งเรือไปสำเภาสมุทร การเสี่ยงโชคดี รูปหล่อสมรสมยาย' WHERE dream_id = 571;
-- Redirect Fix: แส้ -> แซ่
UPDATE dreams SET dream_interpretation = 'ฝันเห็นแส้ หรือแซ่ ฝันว่าถูกตีด้วยแซ่ เจ็บปวดและมีโลหิตไหลออกจากกายเรา ทายว่า จะได้รับทุกขลาภ ที่ป่วยเจ็บจะหาย แต่ต้องเสียเงินทองมาก ที่ได้โชคลาภในการเสี่ยงมักจะมีเคราะห์ในขณะเดียวกัน' WHERE dream_id = 572;
