-- Target 'สตางค์' not found for redirect 'เหรียญเงิน' (ID 612)
-- Redirect Fix: เหรียญ -> เงินทอง
UPDATE dreams SET dream_interpretation = 'ฝันเห็นเหรียญ หรือเงินทอง ฝันว่าได้เงินได้ทอง หรือฝันว่าได้จับเงินทอง ทายว่า ผู้ฝันหรือคนในฝันจะได้เงิน แต่ในพจนานุกรมไทยตีความว่า จะเสียเงิน หรือเสียพนัน ถ้าฝันว่าเสียเงิน ทายว่า จะได้รับเงิน (การฝันถึงเงิน หรือเงินทอง ตำราฝันของไทย ถือว่าเป็นฝันดี แต่ตำราของต่างประเทศส่วนมาก ถือว่าเป็นฝันร้าย)' WHERE dream_id = 619;
-- Fix 623 หิ่งห้อย (Garbled text)
UPDATE dreams SET dream_interpretation = 'ฝันเห็นหิ่งห้อย หรือหิ่งห้อยตัวเดียว ทายว่า สิ่งที่คิดไว้จะสมหวัง การงานจะก้าวหน้า หรือได้รับข่าวดีจากทางไกล' WHERE dream_id = 623;
-- Fix 643 กิ้งก่า (Missing prefix)
UPDATE dreams SET dream_interpretation = 'ฝันเห็นกิ้งก่า เป็นความฝันดี ผู้ฝันจะได้ลาภผลอย่างรวดเร็ว' WHERE dream_id = 643;
-- Fix 645 กษัตริย์
UPDATE dreams SET dream_interpretation = 'ฝันเห็นกษัตริย์ หรือ องค์เจ้าแผ่นดินหรือพระราชินี ท่านจะได้เลื่อนตำปแหน่งยศทางการ หรือในตำแหน่งหน้าที่การงานทั่วไป หรืออาจมีโชคลาภในการเสี่ยงโชคลาภลอย ได้รับข่าวดีจากญาติผู้ใหญ่' WHERE dream_id = 645;
COMMIT;
